import{_ as e,c as o,o as a,a2 as i}from"./chunks/framework.DdOM6S6U.js";const v=JSON.parse('{"title":"Make Horizon Supervisor","description":"","frontmatter":{},"headers":[],"relativePath":"guide/console/generators/make-horizon-supervisor.md","filePath":"guide/console/generators/make-horizon-supervisor.md","lastUpdated":1778363927000}'),t={name:"guide/console/generators/make-horizon-supervisor.md"},r=i('<h1 id="make-horizon-supervisor" tabindex="-1">Make Horizon Supervisor <a class="header-anchor" href="#make-horizon-supervisor" aria-label="Permalink to &quot;Make Horizon Supervisor&quot;">​</a></h1><blockquote><p>Create a Horizon Supervisor configuration file.</p></blockquote><h2 id="command-information" tabindex="-1">Command Information <a class="header-anchor" href="#command-information" aria-label="Permalink to &quot;Command Information&quot;">​</a></h2><ul><li><strong>Signature:</strong> <code>modularous:make:horizon:supervisor</code></li><li><strong>Alias:</strong> <code>modularous:create:horizon:supervisor</code></li><li><strong>Category:</strong> Generators</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><h3 id="run-the-interactive-setup" tabindex="-1">Run the interactive setup <a class="header-anchor" href="#run-the-interactive-setup" aria-label="Permalink to &quot;Run the interactive setup&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:make:horizon:supervisor</span></span></code></pre></div><h2 id="modularous-make-horizon-supervisor" tabindex="-1"><code>modularous:make:horizon:supervisor</code> <a class="header-anchor" href="#modularous-make-horizon-supervisor" aria-label="Permalink to &quot;`modularous:make:horizon:supervisor`&quot;">​</a></h2><p>Interactively generates a Supervisor <code>.conf</code> file for Laravel Horizon. The command:</p><ol><li>Detects the operating system and checks if <code>supervisord</code> is installed. If not, it prints the appropriate install command for the detected platform (Homebrew on macOS, apt/yum on Linux).</li><li>Finds a writable Supervisor configuration directory (<code>/etc/supervisor/conf.d</code>, <code>/etc/supervisord.d</code>, <code>/opt/homebrew/etc/supervisor.d</code>, etc.).</li><li>Prompts for the configuration details listed below.</li><li>Optionally prints the generated config content for review.</li><li>Writes the <code>.conf</code> file to the detected Supervisor directory.</li></ol><p><strong>Interactive prompts:</strong></p><table><thead><tr><th>Prompt</th><th>Default</th></tr></thead><tbody><tr><td>Supervisor config name</td><td><code>b2press-app</code></td></tr><tr><td>PHP binary path</td><td><code>php</code></td></tr><tr><td>Application path</td><td>Current project root</td></tr><tr><td>Artisan command to run</td><td><code>artisan horizon</code></td></tr><tr><td>System user to run as</td><td><code>root</code></td></tr><tr><td>Log file name</td><td><code>horizon</code></td></tr></tbody></table><p>After the file is written, the command prints the <code>supervisorctl reread</code>, <code>update</code>, and <code>start</code> commands needed to activate the new configuration.</p><blockquote><p><strong>Note:</strong> This command is not supported on Windows.</p></blockquote><h3 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h3><ul><li><code>modularous:make:horizon:supervisor</code></li><li><code>modularous:create:horizon:supervisor</code></li></ul><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><h4 id="help-h" tabindex="-1"><code>--help|-h</code> <a class="header-anchor" href="#help-h" aria-label="Permalink to &quot;`--help|-h`&quot;">​</a></h4><p>Display help for the given command. When no command is given display help for the list command</p><ul><li>Accept value: no</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: no</li><li>Default: <code>false</code></li></ul><h4 id="quiet-q" tabindex="-1"><code>--quiet|-q</code> <a class="header-anchor" href="#quiet-q" aria-label="Permalink to &quot;`--quiet|-q`&quot;">​</a></h4><p>Do not output any message</p><ul><li>Accept value: no</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: no</li><li>Default: <code>false</code></li></ul><h4 id="verbose-v-vv-vvv" tabindex="-1"><code>--verbose|-v|-vv|-vvv</code> <a class="header-anchor" href="#verbose-v-vv-vvv" aria-label="Permalink to &quot;`--verbose|-v|-vv|-vvv`&quot;">​</a></h4><p>Increase the verbosity of messages: 1 for normal output, 2 for more verbose output and 3 for debug</p><ul><li>Accept value: no</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: no</li><li>Default: <code>false</code></li></ul><h4 id="version-v" tabindex="-1"><code>--version|-V</code> <a class="header-anchor" href="#version-v" aria-label="Permalink to &quot;`--version|-V`&quot;">​</a></h4><p>Display this application version</p><ul><li>Accept value: no</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: no</li><li>Default: <code>false</code></li></ul><h4 id="ansi-no-ansi" tabindex="-1"><code>--ansi|--no-ansi</code> <a class="header-anchor" href="#ansi-no-ansi" aria-label="Permalink to &quot;`--ansi|--no-ansi`&quot;">​</a></h4><p>Force (or disable --no-ansi) ANSI output</p><ul><li>Accept value: no</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: yes</li><li>Default: <code>NULL</code></li></ul><h4 id="no-interaction-n" tabindex="-1"><code>--no-interaction|-n</code> <a class="header-anchor" href="#no-interaction-n" aria-label="Permalink to &quot;`--no-interaction|-n`&quot;">​</a></h4><p>Do not ask any interactive question</p><ul><li>Accept value: no</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: no</li><li>Default: <code>false</code></li></ul><h4 id="env" tabindex="-1"><code>--env</code> <a class="header-anchor" href="#env" aria-label="Permalink to &quot;`--env`&quot;">​</a></h4><p>The environment the command should run under</p><ul><li>Accept value: yes</li><li>Is value required: no</li><li>Is multiple: no</li><li>Is negatable: no</li><li>Default: <code>NULL</code></li></ul>',38),l=[r];function n(s,d,c,u,h,p){return a(),o("div",null,l)}const f=e(t,[["render",n]]);export{v as __pageData,f as default};
